-- Mural de Tensões: human participation store.
--
-- People scan a tension QR code, pick one of the council roles (strata) and then vote and
-- comment on the proposals of that tension. Their input is stored apart from the synthetic
-- council: nothing here is generated by a model, and every row carries the role the person
-- chose when joining.
--
-- Participation is anonymous by default: the server gives each person a nickname such as
-- "Pesquisa·7f3" and a face, both derived from the random participant id. A person may add
-- their real name at any time (and remove it again); that never changes the nickname or the face.
--
-- Dialect: SQLite 3.35+ (used by `scse mural serve`). The DDL avoids SQLite-only features so it
-- ports to PostgreSQL by swapping INTEGER PRIMARY KEY AUTOINCREMENT for BIGSERIAL and TEXT
-- timestamps for TIMESTAMPTZ. All timestamps are UTC ISO-8601 strings.

PRAGMA foreign_keys = ON;

-- One review session per revision packet (one run of a scenario). The page sends the packet id,
-- so two runs never mix their votes.
CREATE TABLE IF NOT EXISTS mural_session (
    session_id   TEXT PRIMARY KEY,               -- revision packet id, e.g. "merge:1d7c33293ac7"
    scenario_id  TEXT NOT NULL,                  -- scenario the packet belongs to, e.g. "GOV-BR-001"
    run_id       TEXT,                           -- run directory name the packet came from
    created_at   TEXT NOT NULL                   -- when the first person joined this session
);

-- A human who joined a session. The role is one of the eight strata of the council; the person
-- speaks as a human in that role, never as the synthetic seat.
CREATE TABLE IF NOT EXISTS participant (
    participant_id TEXT PRIMARY KEY,             -- random UUID handed to the browser
    session_id     TEXT NOT NULL REFERENCES mural_session(session_id) ON DELETE CASCADE,
    display_name   TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 60), -- anonymous nickname generated at join ("Pesquisa·7f3"); never changes
    stratum_id     TEXT NOT NULL CHECK (stratum_id IN (
                       'regulators','publicOperators','business','research',
                       'civilSociety','workers','affectedGroups','infrastructure')), -- chosen role
    avatar_seed    INTEGER NOT NULL,             -- picks the face drawn for this person (0..9999), derived from participant_id; never changes
    token_hash     TEXT NOT NULL,                -- SHA-256 of the secret the browser sends back; the secret itself is never stored
    identified_name TEXT CHECK (identified_name IS NULL OR length(identified_name) BETWEEN 1 AND 60), -- real name the person chose to show; NULL while anonymous
    identified_at  TEXT,                         -- when the person last set their real name; NULL while anonymous
    joined_tension TEXT,                         -- tension whose QR code brought the person in (NULL if joined from the feed)
    created_at     TEXT NOT NULL,                -- join time
    last_seen_at   TEXT NOT NULL                 -- last request from this person, any kind
);
CREATE INDEX IF NOT EXISTS participant_session ON participant(session_id);

-- Who is looking at which tension right now. One open row per person and tension; a row is
-- closed (left_at set) when the person moves on, or when heartbeats stop for 45 seconds.
CREATE TABLE IF NOT EXISTS presence (
    presence_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    participant_id TEXT NOT NULL REFERENCES participant(participant_id) ON DELETE CASCADE,
    tension_id     TEXT NOT NULL,                -- seed tension id (T1..T6) or "outras"
    entered_at     TEXT NOT NULL,                -- when the person opened the tension
    heartbeat_at   TEXT NOT NULL,                -- last heartbeat from the open page
    left_at        TEXT                          -- NULL while present
);
CREATE INDEX IF NOT EXISTS presence_open ON presence(tension_id, left_at);
CREATE INDEX IF NOT EXISTS presence_participant ON presence(participant_id, left_at);

-- A person's current position on a proposal. One row per person and proposal; changing the
-- position updates the row and the change is kept in mural_event.
CREATE TABLE IF NOT EXISTS vote (
    participant_id TEXT NOT NULL REFERENCES participant(participant_id) ON DELETE CASCADE,
    proposal_id    TEXT NOT NULL,                -- proposal id in the packet, e.g. "M017"
    tension_id     TEXT,                         -- tension the person was in when voting (context, not a key)
    stance         TEXT NOT NULL CHECK (stance IN ('for','amend','against')), -- apoio, pede ajuste, contra
    created_at     TEXT NOT NULL,                -- first vote on this proposal
    updated_at     TEXT NOT NULL,                -- last change of stance
    PRIMARY KEY (participant_id, proposal_id)
);
CREATE INDEX IF NOT EXISTS vote_proposal ON vote(proposal_id);

-- Free-text comment by a person on a proposal. Soft-deleted so the event log stays consistent.
CREATE TABLE IF NOT EXISTS comment (
    comment_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    participant_id TEXT NOT NULL REFERENCES participant(participant_id) ON DELETE CASCADE,
    proposal_id    TEXT NOT NULL,                -- proposal commented on
    tension_id     TEXT,                         -- tension the person was in when commenting
    body           TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 1000), -- comment text as typed
    created_at     TEXT NOT NULL,
    deleted_at     TEXT                          -- set when the author removes the comment
);
CREATE INDEX IF NOT EXISTS comment_proposal ON comment(proposal_id, deleted_at);

-- Append-only log of everything people did, in order. It feeds the live stream of the page
-- (Server-Sent Events, resumable by event_id) and is the audit trail of the session.
CREATE TABLE IF NOT EXISTS mural_event (
    event_id       INTEGER PRIMARY KEY AUTOINCREMENT, -- monotonic; clients resume with Last-Event-ID
    session_id     TEXT NOT NULL REFERENCES mural_session(session_id) ON DELETE CASCADE,
    type           TEXT NOT NULL CHECK (type IN ('joined','entered','left','vote','comment','comment.deleted','identified')),
    participant_id TEXT REFERENCES participant(participant_id) ON DELETE SET NULL,
    tension_id     TEXT,                         -- tension involved, when there is one
    proposal_id    TEXT,                         -- proposal involved, when there is one
    payload        TEXT NOT NULL DEFAULT '{}',   -- JSON with the event details (stance, comment id, identified flag, ...)
    created_at     TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS event_session ON mural_event(session_id, event_id);
